function gis_login(t){if(void 0===mi_ajax_object)return!1;const e="object"==typeof t?t.credential:t;fetch(mi_ajax_object.ajax_url,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:"action=auth_with_google&code="+e+"&nonce="+mi_ajax_object.security}).then((t=>t.json())).then((t=>{t.success?window.location.href=t.data.redirect:console.log(t.data.meesage)}))}document.addEventListener("DOMContentLoaded",(function(){let t=document.querySelectorAll(".tab button");t.length&&t.forEach((e=>{e.addEventListener("click",(function(){if(!e.classList.contains("active")){t.forEach((t=>t.classList.remove("active"))),e.classList.add("active");let o=e.getAttribute("data-tab");document.querySelector("h2.title").innerHTML=e.getAttribute("data-title"),o&&(document.querySelectorAll(".tab-content").forEach((t=>t.classList.add("d-none"))),document.querySelector(`.${o}`).classList.remove("d-none"))}}))}));let e=document.querySelectorAll(".input-field .password-show");e.length&&e.forEach((t=>{t.addEventListener("click",(function(){let e=t.closest(".input-field").querySelector("input");"password"==e.getAttribute("type")?e.setAttribute("type","text"):e.setAttribute("type","password")}))}))}));